ruleExplore.author:
@js:
var d=org.jsoup.Jsoup.parse(src);
var a="";
var td=d.select("td");
if(td.size()>2) a=td.get(2).text();
if(!a){
  var xs=d.select(".media-body .row a");
  if(xs.size()>0) a=xs.last().text();
}
a;

